export class HierarchicalReasoningFramework {
  constructor() {
    this.branches = [];
    this.pubSubSystem = new Map();
  }

  createBranch(id, data) {
    const branch = { id, data, state: 'active' };
    this.branches.push(branch);
    this.pubSubSystem.set(id, []);
    return branch;
  }

  backtrack(branchId) {
    const branch = this.branches.find(b => b.id === branchId);
    if (branch) {
      branch.state = 'backtracked';
      this.pubSubSystem.get(branchId).forEach(callback => callback(branch));
    }
  }

  subscribe(branchId, callback) {
    if (this.pubSubSystem.has(branchId)) {
      this.pubSubSystem.get(branchId).push(callback);
    }
  }

  allocateResources(priorityFn) {
    this.branches.sort((a, b) => priorityFn(b) - priorityFn(a));
    return this.branches;
  }
}